parameters.jsCode:
// Controlla il messaggio arrivato su Telegram.
// - Chi non è in CHAT_AUTORIZZATE riceve il proprio codice chat e nient'altro (nessun costo, nessun download).
// - Senza foto: risponde con le istruzioni.
// - Con la foto: sceglie la versione più grande che Claude può leggere (sotto i 4,5 MB) e la fa scaricare.
const cfg = $input.first().json;
const msg = cfg.message || cfg.edited_message || null;

// Aggiornamenti senza chat (per esempio il bot aggiunto a un gruppo): non si risponde.
if (!msg || !msg.chat) return [];

const chatId = msg.chat.id;
const mittente =
  [msg.from && msg.from.first_name, msg.from && msg.from.last_name].filter(Boolean).join(' ') ||
  (msg.from && msg.from.username) ||
  'qualcuno';
const autorizzate = String(cfg.CHAT_AUTORIZZATE || '')
  .split(/[\s,;]+/)
  .map((s) => s.trim())
  .filter(Boolean);

function rispondi(testo) {
  return [{ json: { azione: 'rispondi', chat_id: chatId, testo } }];
}

if (!autorizzate.includes(String(chatId))) {
  return rispondi(
    'Questo bot è riservato all\'agenzia SDG.\n' +
      'Il tuo codice chat è <code>' + chatId + '</code>: chiedi a chi gestisce n8n ' +
      'di aggiungerlo nel nodo Config, alla voce CHAT_AUTORIZZATE.',
  );
}

const ISTRUZIONI =
  '📸 Mandami una <b>foto del negozio</b>, con l\'insegna ben leggibile.\n' +
  'Se vuoi, nella didascalia scrivi la città o la via (per esempio «via Roma, Torino»): ' +
  'mi aiuta a trovare il negozio giusto su Google.\n\n' +
  'In 2-3 minuti ti rispondo con come è messo su Google, sul sito e sui social, e cosa proporgli.';

// Claude accetta immagini fino a 5 MB: si resta sotto i 4,5 MB per sicurezza.
const PESO_MAX = 4.5 * 1024 * 1024;
let fileId = '';
let peso = 0;
if (Array.isArray(msg.photo) && msg.photo.length) {
  // Telegram manda la stessa foto in più misure, dalla più piccola alla più grande.
  const adatte = msg.photo.filter((f) => !f.file_size || f.file_size <= PESO_MAX);
  const scelta = adatte.length ? adatte[adatte.length - 1] : msg.photo[0];
  fileId = scelta.file_id;
  peso = scelta.file_size || 0;
} else if (msg.document && /^image\//i.test(msg.document.mime_type || '')) {
  if (msg.document.file_size && msg.document.file_size > PESO_MAX) {
    return rispondi('La foto è troppo pesante. Mandala come <b>foto normale</b> (non come file), così Telegram la alleggerisce.');
  }
  fileId = msg.document.file_id;
  peso = msg.document.file_size || 0;
} else if (msg.document || msg.video || msg.video_note || msg.animation) {
  return rispondi('Mi serve una <b>foto</b> (non un video o un altro file).\n\n' + ISTRUZIONI);
} else {
  return rispondi(ISTRUZIONI);
}

return [
  {
    json: {
      azione: 'analizza',
      chat_id: chatId,
      mittente,
      didascalia: String(msg.caption || '').trim().slice(0, 300),
      ricevuta_il: new Date((msg.date || Date.now() / 1000) * 1000).toISOString(),
      file_id: fileId,
      peso_dichiarato: peso,
    },
  },
];

// Controlla la foto scaricata da Telegram e prepara la richiesta a Claude per leggerla:
// nome, tipo di attività, contatti e segni di presenza online.
const scaricata = $input.first();
const m = $('Controlla messaggio').first().json;
const cfg = $('Config').first().json;

function rispondi(testo) {
  return [{ json: { azione: 'rispondi', chat_id: m.chat_id, testo } }];
}

if (!scaricata.binary || !scaricata.binary.data) {
  return rispondi('Non sono riuscito a scaricare la foto da Telegram. Riprova a mandarla tra un momento.');
}
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buffer.length > 4.5 * 1024 * 1024) {
  return rispondi('La foto è troppo pesante. Mandala come <b>foto normale</b> (non come file), così Telegram la alleggerisce.');
}
function tipoImmagine(b) {
  if (b.length > 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'image/jpeg';
  if (b.length > 8 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) return 'image/png';
  if (b.length > 12 && b.toString('ascii', 0, 4) === 'RIFF' && b.toString('ascii', 8, 12) === 'WEBP') return 'image/webp';
  if (b.length > 6 && b.toString('ascii', 0, 4) === 'GIF8') return 'image/gif';
  return null;
}
const mediaType = tipoImmagine(buffer);
if (!mediaType) {
  return rispondi(
    'Non riesco ad aprire questo formato di foto (forse HEIC dell\'iPhone). Mandala come <b>foto normale</b>, non come file.',
  );
}

const SISTEMA = `Sei l'assistente di SDG, un'agenzia di marketing (siti, social, foto e video).
Un collega ha fotografato un negozio dalla strada. Leggi la foto con attenzione e riporta solo quello che si vede davvero.

Cosa ci serve:
- nome dell'attività, scritto come sull'insegna;
- tipo di attività (per esempio pasticceria, parrucchiere, ferramenta, ristorante);
- città e indirizzo, se si leggono sulla foto o nella nota del collega;
- contatti scritti: telefono, sito, profili social;
- segni di presenza online: adesivi (Google, TripAdvisor, TheFork, Glovo, Deliveroo, Just Eat, Satispay...), QR code, nomi di profili;
- com'è la vetrina vista da un'agenzia: insegna, ordine, luce, orari esposti.

Regole:
- Non inventare. Se un dato non si vede, lascia la stringa vuota o la lista vuota.
- Se il nome non si legge con sicurezza, metti "leggibile" a false e spiega perché in "motivo".
  Se però il collega ha scritto il nome nella nota, usalo e metti "leggibile" a true.
- "ricerca_google" è la frase migliore da cercare su Google Maps per trovare questo negozio:
  nome + tipo di attività + via e città se le conosci (dalla foto o dalla nota).
- "osservazioni": al massimo 3 note brevi utili a un'agenzia (per esempio «orari scritti a mano», «insegna sbiadita», «logo diverso tra insegna e tenda»).`;

const nota = m.didascalia
  ? `Nota del collega (può contenere città, via o nome del negozio): «${m.didascalia}»`
  : 'Il collega non ha scritto note.';

const testo = (descrizione) => ({ type: 'string', description: descrizione });
const lista = (descrizione) => ({ type: 'array', items: { type: 'string' }, description: descrizione });

const schema = {
  type: 'object',
  properties: {
    leggibile: { type: 'boolean', description: 'true se il nome dell\'attività si legge con sicurezza' },
    motivo: testo('Se non leggibile: perché (foto mossa, insegna coperta...). Altrimenti stringa vuota'),
    nome_attivita: testo('Nome come scritto sull\'insegna'),
    tipo_attivita: testo('Tipo di attività, in italiano, minuscolo'),
    citta: testo('Città o paese, se si legge sulla foto o nella nota. Altrimenti stringa vuota'),
    indirizzo: testo('Via e numero, se si leggono. Altrimenti stringa vuota'),
    telefono: testo('Telefono scritto sulla vetrina o sull\'insegna'),
    sito: testo('Indirizzo del sito scritto sulla vetrina'),
    profili_social: lista('Nomi o indirizzi di profili social scritti o su adesivi'),
    segni_online: lista('Adesivi, QR code, loghi di piattaforme visibili'),
    insegna: {
      type: 'string',
      enum: ['curata', 'datata o rovinata', 'assente o illeggibile', 'non si vede'],
    },
    vetrina: testo('Una frase su vetrina, luce e ordine, vista da un\'agenzia'),
    osservazioni: lista('Al massimo 3 note brevi utili a un\'agenzia'),
    ricerca_google: testo('Frase da cercare su Google Maps per trovare questo negozio'),
  },
  required: [
    'leggibile', 'motivo', 'nome_attivita', 'tipo_attivita', 'citta', 'indirizzo', 'telefono', 'sito',
    'profili_social', 'segni_online', 'insegna', 'vetrina', 'osservazioni', 'ricerca_google',
  ],
  additionalProperties: false,
};

const richiesta = {
  model: cfg.CLAUDE_MODELLO || 'claude-opus-5-5',
  max_tokens: 16000,
  // Se il modello rifiuta per un filtro di sicurezza, l'API riprova da sola con un modello di riserva.
  fallbacks: 'default',
  output_config: {
    effort: cfg.CLAUDE_EFFORT || 'medium',
    format: { type: 'json_schema', schema },
  },
  system: SISTEMA,
  messages: [
    {
      role: 'user',
      content: [
        { type: 'image', source: { type: 'base64', media_type: mediaType, data: buffer.toString('base64') } },
        { type: 'text', text: nota },
      ],
    },
  ],
};

return [
  {
    json: {
      azione: 'analizza',
      chat_id: m.chat_id,
      mittente: m.mittente,
      didascalia: m.didascalia,
      ricevuta_il: m.ricevuta_il,
      richiesta,
    },
  },
];

// Legge cosa ha visto Claude nella foto e prepara la ricerca su Google Maps.
// ---- comune: leggere le risposte di Claude (lo stesso codice in ogni nodo che ne ha bisogno) ----
// Restituisce il motivo dell'errore, oppure null se la risposta è buona.
function erroreClaude(r) {
  if (!r || typeof r !== 'object') return 'nessuna risposta';
  // Il nodo HTTP, quando fallisce dopo i tentativi, passa avanti { error: ... } (impostazione "On Error: Continue").
  if (r.error && r.type !== 'error') {
    const e = r.error;
    if (typeof e === 'string') return e.slice(0, 300);
    const parti = [e.message, e.description].filter((x) => typeof x === 'string' && x);
    return (parti.join(' — ') || 'errore di collegamento').slice(0, 300);
  }
  if (r.type === 'error') return String((r.error && r.error.message) || 'errore dell\'API').slice(0, 300);
  if (r.stop_reason === 'refusal') {
    const cat = r.stop_details && r.stop_details.category;
    return 'Claude non ha voluto rispondere' + (cat ? ' (' + cat + ')' : '');
  }
  if (r.stop_reason === 'max_tokens') return 'la risposta era troppo lunga ed è stata interrotta';
  if (!Array.isArray(r.content)) return 'risposta senza contenuto';
  return null;
}

function testoClaude(r) {
  return ((r && r.content) || [])
    .filter((b) => b && b.type === 'text' && typeof b.text === 'string')
    .map((b) => b.text)
    .join('');
}

// Per le risposte con output_config.format (JSON garantito dallo schema).
function jsonClaude(r) {
  const errore = erroreClaude(r);
  if (errore) return { errore };
  try {
    return { dati: JSON.parse(testoClaude(r)) };
  } catch (e) {
    return { errore: 'la risposta non era nel formato atteso' };
  }
}

// Stima del costo in dollari, dai token che l'API dichiara. Prezzi di listino per milione di token (novembre 2026).
const PREZZI_CLAUDE = {
  'claude-opus-5-5': [4, 20, 0.2],
  'claude-sonnet-5-5': [2, 10, 0.1],
  'claude-haiku-5-5': [0.1, 0.5, 0.01],
  'claude-fable-5-2': [8, 40, 0.2],
};
function costoClaude(r) {
  if (!r || !r.usage) return 0;
  const u = r.usage;
  const [entrata, uscita, letturaCache] = PREZZI_CLAUDE[r.model] || PREZZI_CLAUDE['claude-opus-5-5'];
  const ricerche = (u.server_tool_use && u.server_tool_use.web_search_requests) || 0;
  return (
    ((u.input_tokens || 0) * entrata +
      (u.cache_creation_input_tokens || 0) * entrata * 1.25 +
      (u.cache_read_input_tokens || 0) * letturaCache +
      (u.output_tokens || 0) * uscita) /
      1e6 +
    ricerche * 0.01
  );
}
// ---- fine comune ----
const r = $input.first().json;
const m = $('Prepara lettura foto').first().json;
const cfg = $('Config').first().json;

function rispondi(testo) {
  return [{ json: { azione: 'rispondi', chat_id: m.chat_id, testo } }];
}
function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const esito = jsonClaude(r);
if (esito.errore) {
  return rispondi(
    '⚠️ Non sono riuscito a far leggere la foto a Claude: ' + esc(esito.errore) + '.\nRiprova tra qualche minuto.',
  );
}

const lettura = esito.dati;
const pulisci = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
for (const k of ['motivo', 'nome_attivita', 'tipo_attivita', 'citta', 'indirizzo', 'telefono', 'sito', 'vetrina', 'ricerca_google']) {
  lettura[k] = pulisci(lettura[k]);
}
for (const k of ['profili_social', 'segni_online', 'osservazioni']) {
  lettura[k] = (Array.isArray(lettura[k]) ? lettura[k] : []).map(pulisci).filter(Boolean).slice(0, 8);
}

let query = lettura.ricerca_google || lettura.nome_attivita;
if (!query || (!lettura.leggibile && !m.didascalia)) {
  return rispondi(
    '🤔 Non riesco a leggere bene l\'insegna' + (lettura.motivo ? ': ' + esc(lettura.motivo) : '') + '.\n' +
      'Prova a rifare la foto più da vicino, con l\'insegna dritta e ben illuminata. ' +
      'Oppure scrivi il nome del negozio nella didascalia.',
  );
}

// Se dalla foto e dalla nota non si capisce la città, si usa quella del Config.
let citta = lettura.citta;
if (!citta && cfg.CITTA_PREDEFINITA) {
  citta = String(cfg.CITTA_PREDEFINITA).trim();
  query = query + ', ' + citta;
}

const nome = lettura.nome_attivita || query;
return [
  {
    json: {
      azione: 'analizza',
      chat_id: m.chat_id,
      mittente: m.mittente,
      didascalia: m.didascalia,
      ricevuta_il: m.ricevuta_il,
      lettura,
      ricerca: { query: query.slice(0, 200), citta },
      costo_usd: costoClaude(r),
      testo:
        '🔎 Ho letto <b>' + esc(nome) + '</b>' + (lettura.tipo_attivita ? ' (' + esc(lettura.tipo_attivita) + ')' : '') + '.\n' +
        'Controllo Google, sito e social: ci vogliono 2-3 minuti.',
    },
  },
];

// Sceglie, tra i risultati di Google Maps, la scheda del negozio fotografato e le dà un voto da 0 a 10.
// Decide anche quale sito controllare.
const r = $input.first().json;
const base = $('Leggi risposta foto').first().json;
const lettura = base.lettura;

// ---------- abbinamento ----------
const PAROLE_VUOTE = new Set([
  'di', 'da', 'del', 'della', 'dello', 'dei', 'degli', 'delle', 'il', 'lo', 'la', 'le', 'gli', 'un', 'una',
  'e', 'ed', 'al', 'alla', 'allo', 'ai', 'agli', 'alle', 'in', 'srl', 'srls', 'snc', 'sas', 'spa', 'the', 'and',
]);
function norma(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}
function parole(s) {
  return norma(s).split(' ').filter((w) => w.length > 1 && !PAROLE_VUOTE.has(w));
}
function somiglianza(a, b) {
  const A = new Set(parole(a));
  const B = new Set(parole(b));
  if (!A.size || !B.size) return 0;
  let comuni = 0;
  for (const w of A) if (B.has(w)) comuni++;
  return comuni / Math.min(A.size, B.size);
}
function cifre(s) {
  return String(s || '').replace(/\D/g, '');
}
function stessoTelefono(a, b) {
  const x = cifre(a);
  const y = cifre(b);
  return x.length >= 7 && y.length >= 7 && x.slice(-7) === y.slice(-7);
}

// Con "On Error: Continue" il nodo HTTP passa avanti { error: ... } se Google ha risposto con un errore.
let erroreApi = '';
if (r.error) {
  erroreApi = typeof r.error === 'string' ? r.error : [r.error.message, r.error.description].filter(Boolean).join(' — ');
  erroreApi = String(erroreApi || 'errore sconosciuto').slice(0, 200);
}
const candidati = Array.isArray(r.places) ? r.places : [];
const nomeCercato = lettura.nome_attivita || base.ricerca.query;

let scelto = null;
let migliore = -1;
const valutati = candidati.map((p, i) => {
  const nome = (p.displayName && p.displayName.text) || '';
  const sim = somiglianza(nomeCercato, nome);
  const tel = stessoTelefono(lettura.telefono, p.nationalPhoneNumber || p.internationalPhoneNumber);
  const via = lettura.indirizzo ? somiglianza(lettura.indirizzo, p.formattedAddress) >= 0.5 : false;
  const punti = sim * 3 + (tel ? 3 : 0) + (via ? 1 : 0) + (i === 0 ? 0.5 : 0);
  return { p, nome, sim, tel, via, punti };
});
for (const v of valutati) {
  if (v.punti > migliore) {
    migliore = v.punti;
    scelto = v;
  }
}
// Un risultato con un nome completamente diverso e senza lo stesso telefono non è il nostro negozio.
if (scelto && scelto.sim === 0 && !scelto.tel) scelto = null;

let abbinamento = 'nessuno';
if (scelto) abbinamento = scelto.tel || scelto.sim >= 0.6 ? 'alta' : scelto.sim >= 0.34 ? 'media' : 'bassa';

// ---------- dati e voto della scheda Google ----------
const google = {
  trovato: !!scelto,
  errore: erroreApi || '',
  abbinamento,
  ricerca: base.ricerca.query,
  altri_risultati: valutati
    .filter((v) => !scelto || v.p !== scelto.p)
    .map((v) => v.nome + ' — ' + (v.p.formattedAddress || ''))
    .slice(0, 3),
  voto: 0,
  dettaglio_voto: [],
};

if (scelto) {
  const p = scelto.p;
  const recensioni = Array.isArray(p.reviews) ? p.reviews : [];
  const date = recensioni.map((x) => Date.parse(x.publishTime)).filter((t) => !isNaN(t));
  const ultima = date.length ? Math.max(...date) : null;
  const giorni = ultima ? Math.floor((Date.now() - ultima) / 86400000) : null;
  Object.assign(google, {
    nome: scelto.nome,
    indirizzo: p.formattedAddress || '',
    maps_url: p.googleMapsUri || '',
    categoria: (p.primaryTypeDisplayName && p.primaryTypeDisplayName.text) || '',
    stato: p.businessStatus || '',
    stelle: typeof p.rating === 'number' ? p.rating : null,
    recensioni: typeof p.userRatingCount === 'number' ? p.userRatingCount : 0,
    telefono: p.nationalPhoneNumber || p.internationalPhoneNumber || '',
    sito: p.websiteUri || '',
    orari: (p.regularOpeningHours && p.regularOpeningHours.weekdayDescriptions) || [],
    foto: Array.isArray(p.photos) ? p.photos.length : 0,
    descrizione: (p.editorialSummary && p.editorialSummary.text) || '',
    giorni_ultima_recensione: giorni,
    ultime_recensioni: recensioni.slice(0, 5).map((x) => ({
      stelle: x.rating,
      quando: x.relativePublishTimeDescription || '',
      testo: String((x.text && x.text.text) || (x.originalText && x.originalText.text) || '').slice(0, 220),
    })),
  });

  const voci = [];
  const voce = (nome, punti, max) => voci.push({ voce: nome, punti, max });
  voce('scheda presente', 2, 2);
  const s = google.stelle || 0;
  voce('stelle', s >= 4.5 ? 2 : s >= 4 ? 1.5 : s >= 3.5 ? 1 : s > 0 ? 0.5 : 0, 2);
  const n = google.recensioni;
  voce('numero di recensioni', n >= 200 ? 2 : n >= 50 ? 1.5 : n >= 15 ? 1 : n >= 1 ? 0.5 : 0, 2);
  voce('orari', google.orari.length ? 1 : 0, 1);
  voce('telefono', google.telefono ? 0.5 : 0, 0.5);
  voce('sito collegato', google.sito ? 1 : 0, 1);
  voce('foto', google.foto >= 10 ? 1 : google.foto >= 3 ? 0.5 : 0, 1);
  voce('recensione negli ultimi 3 mesi', giorni !== null && giorni <= 90 ? 0.5 : 0, 0.5);
  google.dettaglio_voto = voci;
  google.voto = Math.min(10, voci.reduce((t, v) => t + v.punti, 0));
}

// ---------- quale sito controllare ----------
const NON_SITI = [
  ['facebook.com', 'Facebook'], ['fb.com', 'Facebook'], ['fb.me', 'Facebook'], ['instagram.com', 'Instagram'],
  ['tiktok.com', 'TikTok'], ['linktr.ee', 'Linktree'], ['wa.me', 'WhatsApp'], ['whatsapp.com', 'WhatsApp'],
  ['t.me', 'Telegram'], ['linkedin.com', 'LinkedIn'], ['youtube.com', 'YouTube'], ['tripadvisor.', 'TripAdvisor'],
  ['thefork.', 'TheFork'], ['business.site', 'sito gratuito di Google (chiuso nel 2024)'], ['g.page', 'Google'],
  ['google.com', 'Google'], ['goo.gl', 'Google'], ['paginegialle.it', 'PagineGialle'], ['booking.com', 'Booking'],
  ['glovoapp.com', 'Glovo'], ['deliveroo.', 'Deliveroo'], ['justeat.', 'Just Eat'], ['treatwell.', 'Treatwell'],
  ['fresha.com', 'Fresha'], ['uala.', 'Uala'], ['beacons.ai', 'Beacons'], ['linkin.bio', 'link in bio'],
];
// Niente `new URL()`: nei nodi Code di n8n 2.x (task runner) non esiste. Si legge l'indirizzo con le espressioni regolari.
const RE_INDIRIZZO = /^(https?):\/\/(?:[^\/?#@]*@)?(\[[0-9a-f:.]+\]|[a-z0-9.-]+)(:\d{1,5})?([\/?#].*)?$/i;
function normalizzaUrl(u) {
  let s = String(u || '').trim().replace(/\s+/g, '');
  if (!s) return '';
  if (!/^https?:\/\//i.test(s)) s = 'http://' + s.replace(/^\/+/, '');
  const m = s.match(RE_INDIRIZZO);
  if (!m || !/[a-z0-9]\.[a-z0-9]/i.test(m[2])) return '';
  return m[1].toLowerCase() + '://' + m[2].toLowerCase() + (m[3] || '') + (m[4] || '/');
}
function nomeHost(url) {
  const m = String(url || '').match(RE_INDIRIZZO);
  return m ? m[2].toLowerCase().replace(/^www\./, '') : '';
}
function piattaforma(url) {
  const h = nomeHost(url);
  if (!h) return null;
  for (const [dominio, nome] of NON_SITI) {
    if (dominio.endsWith('.') ? h.includes(dominio) : h === dominio || h.endsWith('.' + dominio)) return nome;
  }
  return null;
}

const daGoogle = normalizzaUrl(google.sito);
