  a.statistiche_google = /googletagmanager\.com|google-analytics\.com|gtag\(|GTM-[A-Z0-9]{4,}/.test(h);
  a.pixel_meta = /connect\.facebook\.net\/[^"']*fbevents|fbq\(\s*['"]init/.test(h);
